package com.tuap.backend.auth;
import java.time.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
@Service public class LocalIdentityCreationService {
 private final AuthIdentityDAO identities; private final IdentityResolver users; private final ClienteDAO clientes; private final EntrenadorDAO entrenadores; private final ReauthenticationService reauth; private final PasswordEncoder passwords; private final Clock clock;
 public LocalIdentityCreationService(AuthIdentityDAO i,IdentityResolver u,ClienteDAO c,EntrenadorDAO e,ReauthenticationService r,PasswordEncoder p){identities=i;users=u;clientes=c;entrenadores=e;reauth=r;passwords=p;clock=Clock.systemUTC();}
 @Transactional public AuthIdentityLinkResponse create(AuthenticatedUser user,LocalIdentityCreationRequest request){if(user==null||users.findByIdAndRole(user.userId(),user.role()).isEmpty())throw new AccountInactiveException();if(request==null||!PasswordResetService.isValidPassword(request.password()))throw new PasswordPolicyViolationException();identities.lockActiveByUserIdAndRole(user.userId(),user.role());if(hasLocal(user))throw new LocalIdentityAlreadyExistsException();String email=email(user);if(email==null||email.isBlank())throw new LocalEmailRequiredException();reauth.consumeForCreateLocal(user,request.reauthToken());setPassword(user,request.password());try{identities.saveAndFlush(new AuthIdentity(user.userId(),user.role(),AuthProvider.LOCAL,user.userId().toString(),email,clock.instant()));}catch(DataIntegrityViolationException e){throw new LocalIdentityAlreadyExistsException();}return new AuthIdentityLinkResponse(AuthProvider.LOCAL,AuthIdentityLinkResponse.Status.LINKED);}
 private boolean hasLocal(AuthenticatedUser u){return identities.existsByUserIdAndRoleAndProviderAndActiveTrue(u.userId(),u.role(),AuthProvider.LOCAL);} private String email(AuthenticatedUser u){return users.findByIdAndRole(u.userId(),u.role()).map(AuthenticatedUser::email).orElse(null);} private void setPassword(AuthenticatedUser u,String raw){if(u.role()==Role.CLIENTE){Cliente c=clientes.findById(u.userId()).orElseThrow(AccountInactiveException::new);c.setContrasena(passwords.encode(raw));clientes.save(c);}else{Entrenador e=entrenadores.findById(u.userId()).orElseThrow(AccountInactiveException::new);e.setContrasena(passwords.encode(raw));entrenadores.save(e);}}
}
